```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"

	"github.com/micro/go-micro/v2/config"
	"github.com/micro/go-micro/v2/runtime/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <program> <source_file_name> <struct_name>")
		os.Exit(1)
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	// Read the source code
	data, err := ioutil.ReadFile(sourceFileName)
	if err != nil {
		log.Fatalf("Failed to read file: %v", err)
	}
	defer data.Close()

	// Parse the Go source code
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "", string(data), parser.ParseComments)
	if err != nil {
		log.Fatalf("Failed to parse file: %v", err)
	}

	// Get all fields in the struct
	fields := make([]schema.FieldInfo, 0)
	for _, field := range file.PosFields {
		if field.Name.Type == reflect.Struct && field.Name.Name == structName {
			for i := 0; i < field.Name.NumField(); i++ {
				fieldInfo := schema.FieldInfo{
					Name:   field.Name.Names[i],
					Type:   fmt.Sprintf("%s.%s", structName, field.Name.Names[i]),
					Optional: false,
				}
				fields = append(fields, fieldInfo)
			}
		}
	}

	// Write the generated schema to a file
	outFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		log.Fatalf("Failed to create file: %v", err)
	}
	defer outFile.Close()

	_, err = json.MarshalIndent(&fields, "", "    ")
	if err != nil {
		log.Fatalf("Failed to marshal schema: %v", err)
	}

	fmt.Printf("Generated Avro schema for struct %s.avsc\n", structName)
}
```

### How to Use the Program:

1. Save this code into a new Go file, e.g., `main.go`.
2. Compile and run the program with your source file and struct name as arguments:
   ```sh
   go build -o avro_generator main.go
   ./avro_generator my_struct.go MyStruct
   ```
   Replace `"my_struct.go"` with the path to your Go source file and `"MyStruct"` with the name of the struct you want to convert.
3. The program will generate an Avro schema named `MyStruct.avsc` in the same directory.

This program uses the `encoding/json` package to marshal the list of `schema.FieldInfo` objects into a JSON formatted string which is then written to a file named after the struct. Make sure you have the necessary dependencies installed, such as the `micro/go-micro/v2/config` library if needed.

